import { Component, ElementRef, inject, signal } from '@angular/core';

@Component({
  selector: 'app-side-panel',
  templateUrl: './side-panel.component.html',
  styleUrl: './side-panel.component.scss',
  host: { '(focusout)': 'onFocusOut($event)' },
})
export class SidePanelComponent {
  private readonly element = inject(ElementRef<HTMLElement>);
  readonly isOpen = signal(false);

  toggle(): void {
    this.isOpen.update((open) => !open);
  }

  // Only narrow screens close the panel when focus moves to a control outside it.
  onFocusOut(event: FocusEvent): void {
    if (!this.isOpen() || globalThis.matchMedia('(max-width: 599px)').matches) return;
    const next = event.relatedTarget;
    if (!(next instanceof Node) || this.element.nativeElement.contains(next)) {
      return;
    }
    this.isOpen.set(false);
  }
}
